const scenario=String($input.first().json.body?.scenario??"").trim();
const samples={
 trusted:{
  canonicalBody:'{"eventId":"evt-1001","action":"sync_customer","customerId":"C-1001","amount":129.9}',
  expectedHash:"21e0ffb32b239fe4bf990fa0c922f68c5e666b7923ffe734b399dbf1092b3d64",
  source:"partner-api",targetUrl:"https://api.example.com/customers/C-1001",action:"sync_customer",
  data:{eventId:"evt-1001",customerId:"C-1001",amount:129.9}
 },
 tampered:{
  canonicalBody:'{"eventId":"evt-1002","action":"sync_customer","customerId":"C-1002","amount":8999.5}',
  expectedHash:"897dae642dfa8210ae6e713895b781a02c9aecdb8d8e5f1c028062f68aa403b0",
  source:"partner-api",targetUrl:"https://api.example.com/customers/C-1002",action:"sync_customer",
  data:{eventId:"evt-1002",customerId:"C-1002",amount:8999.5}
 },
 pii:{
  canonicalBody:'{"eventId":"evt-1003","action":"support_ticket","customerId":"C-1003","email":"mina@example.com","phone":"+49-170-1234567","token":"tok_demo_123","message":"VPN problem"}',
  expectedHash:"21f77952c50b823c162c23f91c678dabe1abc4255d905329c1c13b4eac8c6f82",
  source:"support-form",targetUrl:"https://api.example.com/tickets",action:"support_ticket",
  data:{eventId:"evt-1003",customerId:"C-1003",email:"mina@example.com",phone:"+49-170-1234567",token:"tok_demo_123",message:"VPN problem"}
 },
 ssrf:{
  canonicalBody:'{"eventId":"evt-1004","action":"fetch_url","customerId":"C-1004","targetUrl":"http://169.254.169.254/latest/meta-data/"}',
  expectedHash:"a82a0b4f0761b00effd5808a800c2eb31701ef2921ffb89c43cc726101d0d133",
  source:"user-input",targetUrl:"http://169.254.169.254/latest/meta-data/",action:"fetch_url",
  data:{eventId:"evt-1004",customerId:"C-1004",targetUrl:"http://169.254.169.254/latest/meta-data/"}
 },
 destructive:{
  canonicalBody:'{"eventId":"evt-1005","action":"delete_user","customerId":"C-1005","requestedBy":"automation"}',
  expectedHash:"a674bd5094e7f5276ff5753826e6acbcb64fe69a6c88a89c39cff073095910dd",
  source:"internal-agent",targetUrl:"https://api.example.com/users/C-1005",action:"delete_user",
  data:{eventId:"evt-1005",customerId:"C-1005",requestedBy:"automation"}
 }
};
const selected=samples[scenario];
if(!selected)return [{json:{valid:false,scenario,error:"unknown_scenario"}}];
return [{json:{valid:true,scenario,...selected}}];

const x=$input.first().json;
const integrityOk=String(x.computedHash||"")===String(x.expectedHash||"");
let networkAllowed=true,networkReason="allowed";
try{
 const u=new URL(String(x.targetUrl||"https://example.invalid/"));
 const host=u.hostname.toLowerCase();
 const privatePatterns=[
  /^localhost$/,
  /^127\./,
  /^10\./,
  /^192\.168\./,
  /^169\.254\./,
  /^172\.(1[6-9]|2\d|3[0-1])\./,
  /^0\./,
  /^\[?::1\]?$/
 ];
 if(u.protocol!=="https:"){networkAllowed=false;networkReason="non_https_target";}
 if(privatePatterns.some(rx=>rx.test(host))){networkAllowed=false;networkReason="private_or_link_local_target";}
}catch{networkAllowed=false;networkReason="invalid_target_url";}

const destructiveActions=new Set(["delete_user","transfer_money","disable_account","delete_data"]);
const requiresApproval=destructiveActions.has(String(x.action||""));
const actionAllowed=!requiresApproval;

function redact(value){
 if(value===null||value===undefined)return value;
 const s=String(value);
 if(/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s)){
  const [local,domain]=s.split("@");return (local.slice(0,1)||"*")+"***@"+domain;
 }
 if(/^\+?[0-9][0-9\-\s]{6,}$/.test(s))return "***PHONE***";
 if(/^(tok_|sk_|key_|bearer\s)/i.test(s))return "***SECRET_REDACTED***";
 return value;
}
const safeLog={};
for(const [k,v] of Object.entries(x.data||{})){
 if(/token|secret|password|authorization|api.?key/i.test(k))safeLog[k]="***SECRET_REDACTED***";
 else if(/email|phone/i.test(k))safeLog[k]=redact(v);
 else safeLog[k]=v;
}
const piiDetected=Object.keys(x.data||{}).filter(k=>/email|phone|name|address|token|secret|password|authorization|api.?key/i.test(k));
const allowed=Boolean(x.valid&&integrityOk&&networkAllowed&&actionAllowed);

return [{json:{
 ok:true,module:"11",case:x.scenario,
 integrity:{algorithm:"SHA-256",expected:x.expectedHash,computed:x.computedHash,match:integrityOk},
 network:{targetUrl:x.targetUrl,allowed:networkAllowed,reason:networkReason,policy:"HTTPS + public allowlisted destinations; block private/link-local targets"},
 action:{name:x.action,destructive:requiresApproval,requiresApproval,allowed:actionAllowed},
 dataProtection:{detectedSensitiveFields:piiDetected,rawFieldCount:Object.keys(x.data||{}).length,auditLog:safeLog,rule:"Secrets are omitted; selected personal fields are masked in logs."},
 decision:{
  allowed,
  status:allowed?"allow":"block",
  reasons:[
   ...(!integrityOk?["integrity_mismatch"]:[]),
   ...(!networkAllowed?[networkReason]:[]),
   ...(requiresApproval?["human_approval_required"]:[])
  ]
 },
 lesson:x.scenario==="tampered"?"Payload integrity mismatch blocks processing before business action."
  :x.scenario==="pii"?"Sensitive values may be necessary for business processing but must not leak into general logs."
  :x.scenario==="ssrf"?"User-controlled URLs must not reach private or link-local infrastructure."
  :x.scenario==="destructive"?"High-impact actions require an explicit approval boundary outside autonomous workflow logic."
  :"Multiple independent controls must pass before the workflow is allowed to act."
}}];
